values.content:
=You are an expert educator. Create comprehensive study materials from this content.

Generate:
1. **Structured Notes** — Organized by topic with headers, key concepts, and explanations
2. **Flashcards** — 10-15 Q&A pairs for memorization
3. **Quiz Questions** — 5 multiple choice + 3 short answer questions

Return JSON:
{
  "title": "topic title",
  "structured_notes": [
    {"topic": "...", "key_concepts": ["..."], "explanation": "...", "examples": ["..."]}
  ],
  "flashcards": [
    {"front": "question", "back": "answer"}
  ],
  "quiz_multiple_choice": [
    {"question": "...", "options": ["A...", "B...", "C...", "D..."], "correct": "A", "explanation": "..."}
  ],
  "quiz_short_answer": [
    {"question": "...", "model_answer": "..."}
  ],
  "summary": "3-sentence overview of the material"
}

Content:
{{ $json.body.text_content }}

parameters.jsCode:
const items = $input.all();
const aiResponse = items[0].json.message.content;
let parsed;
try {
  parsed = JSON.parse(aiResponse);
} catch(e) {
  parsed = { title: 'Study Notes', structured_notes: [], flashcards: [], quiz_multiple_choice: [], quiz_short_answer: [], summary: aiResponse };
}

// Format notes
const notesHtml = (parsed.structured_notes || []).map(n => {
  const concepts = (n.key_concepts || []).map(c => `<li>${c}</li>`).join('');
  const examples = (n.examples || []).map(e => `<li><em>${e}</em></li>`).join('');
  return `<h3>${n.topic}</h3><p>${n.explanation}</p><strong>Key Concepts:</strong><ul>${concepts}</ul>${examples ? '<strong>Examples:</strong><ul>' + examples + '</ul>' : ''}`;
}).join('\n');

// Format flashcards
const flashcardsHtml = (parsed.flashcards || []).map((f, i) => `<p><strong>Q${i+1}:</strong> ${f.front}<br><strong>A:</strong> ${f.back}</p>`).join('\n');

// Format quiz
const mcHtml = (parsed.quiz_multiple_choice || []).map((q, i) => {
  const opts = (q.options || []).map(o => `<li>${o}</li>`).join('');
  return `<p><strong>${i+1}.</strong> ${q.question}</p><ul>${opts}</ul><p><em>Answer: ${q.correct} — ${q.explanation}</em></p>`;
}).join('\n');

const saHtml = (parsed.quiz_short_answer || []).map((q, i) => `<p><strong>${i+1}.</strong> ${q.question}<br><em>Model answer: ${q.model_answer}</em></p>`).join('\n');

return [{
  json: {
    title: parsed.title || 'Study Notes',
    summary: parsed.summary || '',
    notesHtml,
    flashcardsHtml,
    mcQuizHtml: mcHtml,
    saQuizHtml: saHtml,
    flashcardCount: (parsed.flashcards || []).length,
    quizCount: (parsed.quiz_multiple_choice || []).length + (parsed.quiz_short_answer || []).length
  }
}];

parameters.message:
=<h1>{{ $json.title }}</h1>
<p><em>{{ $json.summary }}</em></p>

<h2>📝 Structured Notes</h2>
{{ $json.notesHtml }}

<h2>🃏 Flashcards ({{ $json.flashcardCount }})</h2>
{{ $json.flashcardsHtml }}

<h2>📋 Quiz — Multiple Choice</h2>
{{ $json.mcQuizHtml }}

<h2>✍️ Quiz — Short Answer</h2>
{{ $json.saQuizHtml }}
